insert into public.quizy_questions (id,land_id,age_band,difficulty,question,options,answer_index,explanation,word,hint) values
('animal-1','animal','old','easy','Which animal is known as the King of the Jungle?','["Lion","Tiger","Elephant","Bear"]'::jsonb,0,'Lions are often called the king of the jungle.','',''),
('animal-2','animal','old','easy','What do baby kangaroos live in?','["A nest","A shell","A pouch","A den"]'::jsonb,2,'A baby kangaroo, called a joey, develops in its mother’s pouch.','',''),
