create table if not exists public.quizy_questions (
 id text primary key, land_id text not null, age_band text not null check(age_band in ('young','old')), difficulty text not null check(difficulty in ('easy','medium','difficult')), question text not null default '', options jsonb not null default '[]'::jsonb, answer_index integer not null default 0, explanation text default '', word text not null default '', hint text not null default '', active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists quizy_questions_lookup on public.quizy_questions(land_id,age_band,difficulty,active);
create table if not exists public.quizy_profiles (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, profile_key text not null, display_name text not null, age_band text not null default 'young' check(age_band in ('young','old')), difficulty text not null default 'easy' check(difficulty in ('easy','medium','difficult')), avatar text not null default '🦊', total_stars integer not null default 0, land_stars jsonb not null default '{}'::jsonb, land_done jsonb not null default '{}'::jsonb, coins integer not null default 0, best_streak integer not null default 0, badges jsonb not null default '[]'::jsonb, unlocked jsonb not null default '[]'::jsonb, theme text not null default 'default', question_history jsonb not null default '{}'::jsonb, music_on boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,profile_key));
create table if not exists public.quizy_attempts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, profile_id uuid references public.quizy_profiles(id) on delete set null, land_id text not null, age_band text not null check(age_band in ('young','old')), difficulty text not null check(difficulty in ('easy','medium','difficult')), score integer not null default 0, total_questions integer not null default 0, correct_answers integer not null default 0, duration_ms bigint, played_at timestamptz not null default now());
create table if not exists public.quizy_achievements (id text primary key, name text not null, description text not null default '', icon text not null default '🏆', coin_reward integer not null default 0, active boolean not null default true);
create table if not exists public.quizy_announcements (id uuid primary key default gen_random_uuid(), title text not null, message text not null, active boolean not null default true, published_at timestamptz not null default now());
alter table public.quizy_questions enable row level security; alter table public.quizy_profiles enable row level security; alter table public.quizy_attempts enable row level security; alter table public.quizy_achievements enable row level security; alter table public.quizy_announcements enable row level security;
drop policy if exists quizy_questions_public_read on public.quizy_questions; create policy quizy_questions_public_read on public.quizy_questions for select to anon,authenticated using(active=true);
drop policy if exists quizy_profiles_owner_all on public.quizy_profiles; create policy quizy_profiles_owner_all on public.quizy_profiles for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists quizy_attempts_owner_select on public.quizy_attempts; create policy quizy_attempts_owner_select on public.quizy_attempts for select to authenticated using(user_id=auth.uid());
drop policy if exists quizy_attempts_owner_insert on public.quizy_attempts; create policy quizy_attempts_owner_insert on public.quizy_attempts for insert to authenticated with check(user_id=auth.uid());
drop policy if exists quizy_achievements_public_read on public.quizy_achievements; create policy quizy_achievements_public_read on public.quizy_achievements for select to anon,authenticated using(active=true);
drop policy if exists quizy_announcements_public_read on public.quizy_announcements; create policy quizy_announcements_public_read on public.quizy_announcements for select to anon,authenticated using(active=true);

on conflict(id) do update set land_id=excluded.land_id,age_band=excluded.age_band,difficulty=excluded.difficulty,question=excluded.question,options=excluded.options,answer_index=excluded.answer_index,explanation=excluded.explanation,word=excluded.word,hint=excluded.hint,updated_at=now();

